    // ---- TryParseGoal ----

    [Fact]
    public void TryParseGoal_GoodGivePayload_RoundTrips()
    {
        var json = """
        {
          "goal_id": "11111111-2222-3333-4444-555555555555",
          "kind": "Give",
          "target": { "name": "Jonathan" },
          "item":   { "name": "Academy Exit Token" },
          "priority": 8,
          "expires_in_seconds": 60,
          "rationale": "Exit Token short_desc says give to Jonathan."
        }
        """;
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Give, g!.Kind);
        Assert.Equal("Jonathan", g.Target.Name);
        Assert.Equal("Academy Exit Token", g.Item?.Name);
        Assert.Equal(8, g.Priority);
        Assert.Equal(60, g.ExpiresInSeconds);
    }

    [Fact]
    public void TryParseGoal_RejectsEmptyTarget()
    {
        var json = """{"kind":"Use","target":{},"rationale":"x","priority":3}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("target", err);
    }

    [Fact]
    public void TryParseGoal_GiveRequiresItem()
    {
        var json = """{"kind":"Give","target":{"name":"Jonathan"},"rationale":"x","priority":5}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("Give", err);
    }

    [Fact]
    public void TryParseGoal_FellowshipQuitParsesWithoutTarget()
    {
        // FellowshipQuit is a self/social action with no world target — like Recall,
        // it must parse with an empty/absent target (else the capability is dead).
        var json = """{"kind":"FellowshipQuit","rationale":"leave the group","priority":4}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.FellowshipQuit, g!.Kind);
    }

    [Fact]
    public void TryParseGoal_FellowshipRecruitRequiresTarget()
    {
        // FellowshipRecruit is a player-DIRECTED action (unlike Create/Quit): it is NOT
        // exempt from the empty-target rejection, so a targetless recruit must be rejected
        // and fall back rather than dispatch a recruit with no player to invite.
        var json = """{"kind":"FellowshipRecruit","rationale":"invite someone","priority":4}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("target", err);
    }

    [Fact]
    public void TryParseGoal_FellowshipRecruitWithTargetParses()
    {
        var json = """{"kind":"FellowshipRecruit","target":{"name":"Galad"},"rationale":"invite a nearby player","priority":4}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.FellowshipRecruit, g!.Kind);
        Assert.Equal("Galad", g.Target.Name);
    }

    [Fact]
    public void TryParseGoal_FellowshipCreateParsesWithoutTarget()
    {
        // An unnamed FellowshipCreate must parse (the dispatch defaults the name);
        // it is a self/social action, not a world-target verb.
        var json = """{"kind":"FellowshipCreate","rationale":"form a group","priority":4}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.FellowshipCreate, g!.Kind);
    }

    [Fact]
    public void TryParseGoal_NamedFellowshipCreateCarriesName()
    {
        // A NAMED FellowshipCreate still parses and carries the name through to the
        // dispatch (the empty-target exemption only skips rejection; a present name
        // makes the target non-empty and flows through unchanged).
        var json = """{"kind":"FellowshipCreate","target":{"name":"Alpha Squad"},"rationale":"team up","priority":4}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.FellowshipCreate, g!.Kind);
        Assert.Equal("Alpha Squad", g.Target.Name);
    }

    [Fact]
    public void TryParseGoal_AcceptsItemOnlySelfUse()
    {
        // Self-Use (read / activate an inventory item ON yourself) carries the
        // item in `item` and no world target — like Wield. The parser must accept
        // it (the Motor's self-Use dispatch sends GameActionUse at the item).
        var json = """{"kind":"Use","item":{"name":"Letter From Home"},"rationale":"read it","priority":5}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Use, g!.Kind);
        Assert.Equal("Letter From Home", g.Item?.Name);
        Assert.True(g.Target.IsEmpty);
    }

    [Fact]
    public void TryParseGoal_AcceptsItemUseWithExplicitEmptyTarget()
    {
        // An explicit empty target object alongside a non-empty item is the same
        // item-only self-Use shape and must parse.
        var json = """{"kind":"Use","target":{},"item":{"name":"Mana Charge"},"rationale":"activate","priority":4}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Use, g!.Kind);
        Assert.Equal("Mana Charge", g.Item?.Name);
    }

    [Fact]
    public void TryParseGoal_StillRejectsItemlessUseWithEmptyTarget()
    {
        // A Use with neither a target NOR an item is still nonsense — reject it.
        var json = """{"kind":"Use","target":{},"rationale":"x","priority":3}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("target", err);
    }

    [Fact]
    public void TryParseGoal_AcceptsLegacyTargetPlusItemUse()
    {
        // Backward-compat at the PARSER level: the older self-Use shape (a name in
        // `target` plus the item) still parses. (The Motor only self-dispatches when
        // the target is empty or names self, so the clean item-only shape is now the
        // preferred form; this test asserts only that the legacy JSON still parses.)
        var json = """{"kind":"Use","target":{"name":"<your-name>"},"item":{"name":"Letter From Home"},"rationale":"read","priority":5}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Use, g!.Kind);
        Assert.Equal("Letter From Home", g.Item?.Name);
    }

    [Fact]
    public void TryParseGoal_RejectsGarbage()
    {
        Assert.False(LlmGoalPolicy.TryParseGoal("not json at all", out _, out _));
    }

    [Fact]
    public void TryParseGoal_ParsesJsonWrappedInLabeledCodeFence()
    {
        // Some chat models (observed: deepseek-v3) wrap their goal JSON in a
        // Markdown ```json fence despite the prompt asking for raw JSON.
        var json = "```json\n" + """
        {
          "kind": "Attack",
          "target": { "name": "Drudge Slinker" },
          "rationale": "winnable",
          "priority": 7
        }
        """ + "\n```";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Attack, g!.Kind);
        Assert.Equal("Drudge Slinker", g.Target.Name);
    }

    [Fact]
    public void TryParseGoal_ParsesJsonWrappedInBareCodeFence()
    {
        var json = "```\n" + """
        {
          "kind": "Explore",
          "target": { "name": "anywhere" },
          "rationale": "scout",
          "priority": 4
        }
        """ + "\n```";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
