    [Fact]
    public void TryParseGoal_ParsesSingleLineFencedJson()
    {
        var json = """```{"kind":"Recall","rationale":"escape","priority":9}```""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
