    [Fact]
    public void StripJsonCodeFence_LeavesRawJsonUnchanged()
    {
        var raw = """{"kind":"Recall","rationale":"x","priority":3}""";
        Assert.Equal(raw, LlmGoalPolicy.StripJsonCodeFence(raw));
    }

    [Fact]
    public void StripJsonCodeFence_IsIdempotent()
    {
        var fenced = "```json\n{\"kind\":\"Recall\"}\n```";
        var once = LlmGoalPolicy.StripJsonCodeFence(fenced);
        var twice = LlmGoalPolicy.StripJsonCodeFence(once);
        Assert.Equal(once, twice);
        Assert.Equal("{\"kind\":\"Recall\"}", once);
    }

    [Fact]
    public void StripJsonCodeFence_HandlesNullAndEmpty()
    {
        Assert.Equal(string.Empty, LlmGoalPolicy.StripJsonCodeFence(null));
        Assert.Equal(string.Empty, LlmGoalPolicy.StripJsonCodeFence(""));
    }

    [Fact]
    public void StripJsonCodeFence_DoesNotEatBraceWhenTagLineCarriesJson()
    {
        // A fence whose first line already carries the object (no language tag)
        // must keep the braces intact.
        var fenced = "```{\"kind\":\"Recall\"}\n```";
        Assert.Equal("{\"kind\":\"Recall\"}", LlmGoalPolicy.StripJsonCodeFence(fenced));
    }

    [Fact]
    public void TryParseGoal_RecallParsesWithoutTarget()
    {
        // Recall is a self-action with no world target; it must parse even
        // though every other verb requires a non-empty target selector.
        var json = """{"kind":"Recall","rationale":"stuck on a ledge, nothing frees me","priority":9}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Recall, g!.Kind);
        Assert.True(g.Target.IsEmpty);
    }

    [Fact]
    public void TryParseGoal_ExploreWithDirection_ParsesHeading()
    {
        // An Explore goal may carry an optional 8-way compass `direction` that
        // steers the outdoor frontier excursion.
        var json = """{"kind":"Explore","target":{"name":"anywhere"},"direction":"southeast","rationale":"barren north, try SE","priority":3}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Explore, g!.Kind);
        Assert.Equal("southeast", g.Direction);
    }

    [Fact]
    public void TryParseGoal_ExploreWithoutDirection_DirectionNull()
    {
        // Direction is optional — a plain Explore leaves it null (undirected).
        var json = """{"kind":"Explore","target":{"name":"anywhere"},"rationale":"x","priority":3}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Null(g!.Direction);
    }

    [Fact]
    public void TryParseGoal_NonRecallVerbStillRequiresTarget()
    {
        // The Recall exception must NOT relax target validation for other
        // verbs: an Attack with no target is still rejected.
        var json = """{"kind":"Attack","rationale":"x","priority":3}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("target", err);
    }

    [Fact]
    public void TryParseGoal_WieldItemOnly_ParsesWithoutTarget()
    {
        // The LLM legitimately emits a Wield with the weapon in `item` and a
        // null/absent target (the prompt schema never directs target=self for
        // Wield). The Motor's Wield dispatch reads goal.Item, so this must
        // parse instead of being discarded to the heuristic fallback.
        var json = """{"kind":"Wield","target":null,"item":{"name":"Acid Ken"},"rationale":"arm up","priority":10}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Wield, g!.Kind);
        Assert.Equal("Acid Ken", g.Item!.Name);
        // Target is normalized to a non-null empty selector so downstream
        // `goal.Target.*` consumers never dereference null.
        Assert.NotNull(g.Target);
        Assert.True(g.Target.IsEmpty);
    }

    [Fact]
    public void TryParseGoal_WieldItemOnly_OmittedTarget_Parses()
    {
        // Same as above but the target field is omitted entirely (not explicit
        // null) — the canonical model output shape.
        var json = """{"kind":"Wield","item":{"name":"Shortbow"},"rationale":"arm up","priority":9}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Wield, g!.Kind);
        Assert.Equal("Shortbow", g.Item!.Name);
    }

    [Fact]
    public void TryParseGoal_WieldWithEmptyTargetAndNoItem_Rejected()
    {
        // A Wield carrying neither a target nor an item has nothing to wield —
        // still rejected.
        var json = """{"kind":"Wield","target":{},"item":null,"rationale":"x","priority":5}""";
        Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err));
        Assert.Contains("target", err);
    }

    [Fact]
    public void TryParseGoal_WieldWithTargetOnly_StillParses()
    {
        // The canonical fallback shape (target=self/weapon, item null) must keep
        // working — the relaxation only ADDS the item-only path.
        var json = """{"kind":"Wield","target":{"name":"self"},"item":null,"rationale":"x","priority":6}""";
        Assert.True(LlmGoalPolicy.TryParseGoal(json, out var g, out var err), err);
        Assert.Equal(GoalKind.Wield, g!.Kind);
    }

    [Fact]
    public void TryParseGoal_NonWieldNonUseItemOnly_StillRejected()
    {
        // The item-only relaxation is scoped to Wield and Use (their object is an
        // inventory item that acts on the user). Attack/Talk/Pickup with an item
        // but no target are still rejected — their primary object is the target.
        foreach (var kind in new[] { "Attack", "Talk", "Pickup" })
        {
            var json = $$"""{"kind":"{{kind}}","target":null,"item":{"name":"Acid Ken"},"rationale":"x","priority":4}""";
            Assert.False(LlmGoalPolicy.TryParseGoal(json, out _, out var err), $"{kind} item-only should reject");
            Assert.Contains("target", err);
        }
    }

    [Fact]
    public void BuildUserPrompt_Schema_AdvertisesRecallVerb()
    {
        // The Recall verb must appear in the kind enum so the LLM may emit it —
        // always present, independent of the cp-2408-gated STUCK ESCAPE rule.
        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), new EventStream(), null);
        Assert.Contains("\"Recall\"", prompt);
    }

    [Fact]
    public void BuildUserPrompt_StuckEscapeRule_RendersOnBlockedRejection_OmittedOtherwise()
    {
        // cp-2408: the STUCK ESCAPE (Recall last-resort) rule is paired with the
        // BLOCKED rule and gated on a recent Blocked/Unreachable geometry
        // rejection — the only situation in which Recall-to-escape is actionable.
        var blocked = new EventStream();
        blocked.Append(new StreamEvent { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected, ErrorLabel = "Blocked" });
        var stuck = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), blocked, null);
        Assert.Contains("STUCK ESCAPE", stuck);
        Assert.Contains("Recall{}", stuck);

        // Moving freely (no geometry rejection) -> the rule is gated off.
        Assert.DoesNotContain("STUCK ESCAPE",
            LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), new EventStream(), null));
    }

    [Fact]
    public void BuildUserPrompt_PursueUnseenObjectives_IncludesNamedTargetNowVisibleClause()
    {
        // A directive's named target may ALREADY be in `Visible nearby` even when
        // the text placed it elsewhere (e.g. a role named "in the next room" while
        // that npc is in view). The PURSUE UNSEEN OBJECTIVES rule must tell the bot
        // the visible npc IS that target — Talk it now, do not grind past it.
        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), new EventStream(), null);
        Assert.Contains("THE TARGET MAY ALREADY BE IN VIEW", prompt);
    }

    [Fact]
    public void BuildUserPrompt_RefusedGiveRule_RendersOnRepeatedGive_OmittedOtherwise()
    {
        // cp give-rule-defer-shortdesc: when the bot loops a Give of the same item
        // to the same npc (the server refuses it), the rule fires to defer to the
        // item's short_desc (named recipient -> Talk/prerequisite) or, when no item
        // names the npc, redirect to Use / a different recipient. Gated on the
        // bot's OWN repeated Give-emission history so it costs zero budget otherwise.
        var giveLoop = new EventStream();
        giveLoop.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Give target=name=\"Greeter\" item=name=\"Stone\" source=llm:test",
        });
        giveLoop.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Give target=name=\"Greeter\" item=name=\"Stone\" source=llm:test",
        });
        Assert.Contains("A REFUSED GIVE",
            LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), giveLoop, null));

        // No repeated Give -> the rule is gated off.
        Assert.DoesNotContain("A REFUSED GIVE",
            LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), new EventStream(), null));
    }

    [Fact]
    public void BuildUserPrompt_RefusedGiveRule_OmittedForSingleGive()
    {
        // A SINGLE Give is not a loop — the rule needs a repeat (>=2 same-target
        // Give emissions) to fire, so it stays off after one Give.
        var oneGive = new EventStream();
        oneGive.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Give target=name=\"Greeter\" item=name=\"Stone\" source=llm:test",
        });
        Assert.DoesNotContain("A REFUSED GIVE",
            LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), oneGive, null));
    }

    [Fact]
    public void BuildUserPrompt_RefusedGiveRule_OmittedForDifferentItemsToSameNpc()
    {
        // The bot trying DIFFERENT items on the same npc is experimenting, NOT
        // looping one refused Give — the gate keys on target+item, so two
        // different items handed to one npc must NOT trip the rule (which would
        // wrongly scold a legitimate item-swap).
        var es = new EventStream();
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Give target=name=\"Greeter\" item=name=\"Apple\" source=llm:test",
        });
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Give target=name=\"Greeter\" item=name=\"Stone\" source=llm:test",
        });
        Assert.DoesNotContain("A REFUSED GIVE",
            LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), es, null));
    }

    [Fact]
    public void BuildUserPrompt_RefusedGiveRule_RendersBothBranches_WhenGiveLoops()
    {
        // The refined rule must carry BOTH branches: defer to an item's short_desc
        // that names THIS npc as the recipient (a refusal then = a missing
        // prerequisite, keep the npc + Talk it first), and otherwise the
        // wrong-verb/target redirect (try Use / a different npc). This pins that
        // the named-recipient branch (the give-rejected flaw fix) is present.
        var giveLoop = new EventStream();
        for (var i = 0; i < 2; i++)
            giveLoop.Append(new StreamEvent
            {
                Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
                Text = "Give target=name=\"Greeter\" item=name=\"Stone\" source=llm:test",
            });
        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), giveLoop, null);
        Assert.Contains("DEFER TO THE ITEM'S INSTRUCTION", prompt); // unique rule marker
        Assert.Contains("intended recipient", prompt);              // named-recipient branch
        Assert.Contains("Use{item}", prompt);                       // unnamed -> wrong-verb branch
    }

    // ---- ## Server hints — HeardSpeech (local NPC speech perception) -------
    // HearSpeech (0x02BB) is the spoken-aloud sibling of the directed Tell
    // (NpcDialog). The receive loop appends a non-self HeardSpeech event; it
    // renders in `## Server hints` so the brain perceives what a nearby player
    // would hear. It is deliberately NON-salient (never wakes the LLM by
    // itself) so ambient speech volume cannot drive a deliberation per line.

    [Fact]
    public void BuildUserPrompt_ServerHints_RendersHeardSpeech()
    {
        var heard = new EventStream();
        heard.AppendHeardSpeech(new StreamEvent
        {
            Sequence = -1,
            Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.HeardSpeech,
            Name = "Nearby Speaker",
            Text = "a spoken line",
            ChatType = 3,
        });

        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), heard, null);

        // Asserted on the whole prompt (not a CapsuleSection slice): the rules
        // block mentions `## Server hints` in backticks before the real section,
        // so a header-substring slice would grab the wrong span. The companion
        // OmitsHeardSpeechWhenNoSpeechHeard test guarantees the conditional.
        Assert.Contains("HeardSpeech from=\"Nearby Speaker\"", prompt);
        Assert.Contains("a spoken line", prompt);
    }

    [Fact]
    public void BuildUserPrompt_ServerHints_OmitsHeardSpeechWhenNoSpeechHeard()
    {
        // Conditional capsule: with no heard speech (the common case, e.g. the
        // entire tutorial), nothing about HeardSpeech renders — zero prompt cost.
        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), new EventStream(), null);
        Assert.DoesNotContain("HeardSpeech", prompt);
    }

    [Fact]
    public void IsSalientKind_HeardSpeech_IsNotSalient()
    {
        // Call-volume contract: ambient local speech (repeated creature emotes,
        // other players'/bots' chatter) must NOT wake the LLM. HeardSpeech is
        // perception-only — it is surfaced when the LLM is already deliberating,
        // never as a deliberation trigger. Regressing this would bankrupt the
        // LLM with a round-trip per spoken line.
        Assert.False(LlmGoalPolicy.IsSalientKind(EventKind.HeardSpeech));
        // It must also not interrupt the autonomous combat chain.
        Assert.False(LlmGoalPolicy.IsChainInterruptingKind(EventKind.HeardSpeech));
    }

    // ── ## Held-item objectives (directive pinned to a held item) ─────────
    // A one-time "do X with this item" server/NPC directive scrolls past the
    // earliest-N / most-recent-M render caps of the directive capsules while the
    // bot still HOLDS the item it names. The held-item capsule re-surfaces it,
    // keyed by the bot's OWN inventory item-name matched against the server's OWN
    // directive text, until the item leaves the pack.

    private static WorldStateProjection BuildWorldHoldingItems(params string[] itemNames) => new()
    {
        Self = new SelfProjection
        {
            Guid = SelfGuid, Name = "Headless", Landblock = 0xAAB5u, CellId = 0xAAB50003u,
            PositionX = 1f, PositionY = 2f, PositionZ = 3f, HealthFraction = 1.0f,
        },
        Inventory = itemNames
            .Select((n, idx) => new InventoryItemProjection
            {
                Guid = (uint)(0x50001000 + idx), Name = n, Wcid = (uint)(1000 + idx),
            })
            .ToArray(),
        Visible = System.Array.Empty<VisibleObjectProjection>(),
    };

    private static void AppendPopup(EventStream es, string text) =>
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = text,
        });

    private static void AppendNpcDialog(EventStream es, string speaker, string text) =>
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog,
            Name = speaker, Text = text,
        });

    // The text of the "## Held-item objectives" capsule only (up to the next
    // "## " header), or null when the capsule is absent.
    private static string? HeldItemCapsule(string prompt)
    {
        const string header = "## Held-item objectives";
        var start = prompt.IndexOf(header, StringComparison.Ordinal);
        if (start < 0) return null;
        var next = prompt.IndexOf("\n## ", start + header.Length, StringComparison.Ordinal);
        return next < 0 ? prompt[start..] : prompt[start..next];
    }

    // Drives the target directive into the "mushy middle": past the earliest-6
    // render cap (6 fillers first) and out of the most-recent-4 window (4 fillers
    // after), but still inside the 24-deep persistent store.
    private static EventStream MushyMiddlePopup(string targetText)
    {
        var es = new EventStream();
        for (var i = 0; i < 6; i++) AppendPopup(es, $"tutorial filler popup before {i}");
        AppendPopup(es, targetText);
        for (var i = 0; i < 4; i++) AppendPopup(es, $"tutorial filler popup after {i}");
        return es;
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_RendersDirectiveNamingHeldItem()
    {
        // A held item whose turn-in directive has scrolled out of the rendered
        // directive lists is re-surfaced verbatim, tied to the item name.
        var es = MushyMiddlePopup("Return the Academy Token to the Training Master in the Practice Area.");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Academy Token"), es, null);

        Assert.Contains("## Held-item objectives", prompt);
        Assert.Contains("Academy Token", prompt);
        Assert.Contains("Return the Academy Token to the Training Master", prompt);
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_OmittedWhenItemNotHeld()
    {
        // The SAME mushy-middle directive, but the bot does NOT hold an item the
        // text names — the capsule must not pin a directive for an item it lacks.
        var es = MushyMiddlePopup("Return the Academy Token to the Training Master in the Practice Area.");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Bruised Apple"), es, null);

        Assert.DoesNotContain("## Held-item objectives", prompt);
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_NotRepeatedWhenAlreadyShownAbove()
    {
        // When the directive is still within the rendered `## Early server
        // directives` slice (here it is the FIRST/only popup, so earliest-6 shows
        // it), the held-item capsule must NOT duplicate it.
        var es = new EventStream();
        AppendPopup(es, "Return the Academy Token to the Training Master in the Practice Area.");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Academy Token"), es, null);

        Assert.Contains("## Early server directives", prompt);
        Assert.Contains("Return the Academy Token to the Training Master", prompt);
        Assert.DoesNotContain("## Held-item objectives", prompt);
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_OmittedWhenNoDirectiveNamesHeldItem()
    {
        // Held items but no persisted directive naming any of them: no capsule,
        // zero prompt cost (no false pin on generic flavor that omits the name).
        var es = MushyMiddlePopup("A generic tutorial tip that names no carried item.");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Academy Token", "Bruised Apple"), es, null);

        Assert.DoesNotContain("## Held-item objectives", prompt);
