    [Fact]
    public void BuildUserPrompt_HeldItemObjective_WordBoundary_NoFalsePositiveSubstring()
    {
        // A short held-item name must match only as a WHOLE token: holding "Key"
        // must NOT pin a directive that merely contains "monkey".
        var es = MushyMiddlePopup("A wild monkey scampers past; nothing to do here.");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Key"), es, null);

        Assert.DoesNotContain("## Held-item objectives", prompt);
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_NpcDialogPinnedWithSpeaker()
    {
        // The directive can be an NPC-spoken line; when it names the held item it
        // pins with the speaker attribution. NPC dialogs render earliest-4 + a
        // recent-8 sliding window, so push the target into the mushy middle:
        // 4 filler dialogs before, the target, then enough after (>8) to also
        // clear the recent window.
        var es = new EventStream();
        for (var i = 0; i < 4; i++) AppendNpcDialog(es, "Greeter", $"filler npc line {i}");
        AppendNpcDialog(es, "Training Master", "Bring the Academy Token back to me when you are ready.");
        for (var i = 0; i < 9; i++) AppendNpcDialog(es, "Greeter", $"later filler npc line {i}");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Academy Token"), es, null);

        var capsule = HeldItemCapsule(prompt);
        Assert.NotNull(capsule);
        Assert.Contains("from \"Training Master\"", capsule);
        Assert.Contains("Bring the Academy Token back to me", capsule);
    }

    [Fact]
    public void BuildUserPrompt_HeldItemObjective_MostRecentNamingDirectiveWins()
    {
        // Two mushy-middle directives name the held item; the later (higher-seq)
        // one is the current instruction and is the one surfaced IN THE CAPSULE
        // (the older line may still echo in `## Server hints`, so assert on the
        // capsule slice, not the whole prompt).
        var es = new EventStream();
        for (var i = 0; i < 6; i++) AppendPopup(es, $"filler popup {i}");
        AppendPopup(es, "Old step: fetch the Academy Token from the chest.");
        AppendPopup(es, "New step: Return the Academy Token to the Training Master.");
        for (var i = 0; i < 4; i++) AppendPopup(es, $"later filler popup {i}");
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildWorldHoldingItems("Academy Token"), es, null);

        var capsule = HeldItemCapsule(prompt);
        Assert.NotNull(capsule);
        Assert.Contains("Return the Academy Token to the Training Master", capsule);
        Assert.DoesNotContain("fetch the Academy Token from the chest", capsule);
    }

    [Theory]
    [InlineData("Return the Academy Token to the Master.", "Academy Token", true)]
    [InlineData("a wild monkey appears", "Key", false)]       // substring inside a word
    [InlineData("cross the milestone marker", "Stone", false)] // substring inside a word
    [InlineData("drop the Key in the lock", "Key", true)]      // whole word, punctuation/space bounded
    [InlineData("", "Key", false)]
    [InlineData("anything", "", false)]
    public void DirectiveNamesItem_MatchesWholeTokenOnly(string text, string name, bool expected)
    {
        Assert.Equal(expected, LlmGoalPolicy.DirectiveNamesItem(text, name));
    }

    [Fact]
    public void IsInflightStuck_NoCallInFlight_NeverStuck()
    {
        // null start time = nothing in flight; the watchdog must never fire.
        Assert.False(LlmGoalPolicy.IsInflightStuck(null, DateTimeOffset.UtcNow, TimeSpan.FromSeconds(120)));
    }

    [Theory]
    [InlineData(0, false)]     // just kicked off
    [InlineData(60, false)]    // at the primary call-timeout CTS, still under the wall
    [InlineData(119, false)]   // under the hard wall
    [InlineData(120, true)]    // exactly at the hard wall -> abandon
    [InlineData(600, true)]    // long hang (live wedge was ~26 min) -> abandon
    public void IsInflightStuck_FiresOnlyAtOrPastTheHardWall(int ageSeconds, bool expected)
    {
        var now = DateTimeOffset.UtcNow;
        var startedAt = now - TimeSpan.FromSeconds(ageSeconds);
        Assert.Equal(expected, LlmGoalPolicy.IsInflightStuck(startedAt, now, TimeSpan.FromSeconds(120)));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_ReturnsTheInterruptingKind()
    {
        // Diagnostic (cp2925 pattern): name the specific event-kind that starves
        // the combat chain so a gate:chain-interrupting-event no-mint is traceable.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "hi" });
        Assert.Equal(EventKind.NpcDialog, LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_NullForNonInterruptingEvent()
    {
        // A kill's own ServerMessage ("you have slain ...") is ordinary combat
        // progress, NOT a chain interrupter — must return null.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ServerMessage, Text = "you have slain a foe" });
        Assert.Null(LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_RespectsFloor()
    {
        // An interrupting event BELOW the floor (already considered at the last
        // LLM look) must not be re-counted as new.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "old" });
        var floor = es.NextSequence;
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ServerMessage, Text = "noise" });
        Assert.Null(LlmGoalPolicy.FirstChainInterruptingKindSince(es, floor));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_ReturnsNewestInterruptingKind()
    {
        // Newest-first: the most recent interrupter is reported.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "earlier" });
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "later" });
        Assert.Equal(EventKind.PopupString, LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_RepeatedPopupAlreadySeen_NotInterrupting()
    {
        // Re-broadcast tutorial flavor: the bot already saw this exact popup (below
        // the floor); the verbatim re-emission since the floor must NOT preempt the
        // autonomous kill-chain (it carries no new information).
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "double-click the body to loot" });
        var floor = es.NextSequence;
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "double-click the body to loot" });
        Assert.Null(LlmGoalPolicy.FirstChainInterruptingKindSince(es, floor));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_NovelDialogAfterRepeat_StillInterrupts()
    {
        // A DIFFERENT dialog line since the floor is genuinely new -> still
        // interrupts so it reaches the LLM, even though an earlier (different) line
        // exists.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "aim high or low" });
        var floor = es.NextSequence;
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "adjust your slider" });
        Assert.Equal(EventKind.NpcDialog, LlmGoalPolicy.FirstChainInterruptingKindSince(es, floor));
    }

    [Fact]
    public void IsRepeatedDialogText_VerbatimRepeat_True()
    {
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "tip" });
        var dup = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "tip" });
        Assert.True(LlmGoalPolicy.IsRepeatedDialogText(es, dup));
    }

    [Fact]
    public void IsRepeatedDialogText_FirstOccurrence_False()
    {
        var es = new EventStream();
        var first = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "tip" });
        Assert.False(LlmGoalPolicy.IsRepeatedDialogText(es, first));
    }

    [Fact]
    public void BuildRunSummaryLine_FormatsProgressionAndTriggers()
    {
