        var zero = LlmGoalPolicy.BuildRunSummaryLine(
            decisions: 5, triggerCounts: triggers, distinctLandblocks: 1,
            lastLandblock: 0xA9B4u, level: 13, totalXp: 250000L, model: "m",
            unspent: 0L);
