        { Guid = 0xAAAu, Name = "Apple", IsCorpse = false, IsMonster = false };
        var world = WorldWithVisible(apple);
        Assert.Null(LlmGoalPolicy.TryResolvePickupUseContainer(
            PickupGoalTo("Apple"), world, new EventStream()));
