            new VisibleObjectProjection { Guid = 0x7A9B0002u, Name = "Chest", IsChest = true, IsStuck = true });
        Assert.Null(LlmGoalPolicy.TryResolvePickupUseContainer(
            PickupGoalTo("Chest"), world, new EventStream()));
    }

