    public void ExploreLoopedVendor_NonExploreGoal_ReturnsNull()
    {
        var es = ExploreEmissionsTo("Blacksmith", 3);
        var use = new Goal { Kind = GoalKind.Use, Target = new Selector { Name = "Blacksmith" } };
        Assert.Null(LlmGoalPolicy.TryResolveExploreLoopedVendor(
            use, WorldWithVisible(VendorObj(0xBA9u, "Blacksmith")), es, ExploreVendorSince));
    }

    [Fact]
    public void ExploreLoopedVendor_AmbiguousTwoVendors_ReturnsNull()
    {
        var world = WorldWithVisible(
            VendorObj(0x7A9B0001u, "Blacksmith"), VendorObj(0x7A9B0002u, "Blacksmith"));
        var es = ExploreEmissionsTo("Blacksmith", 3);
        Assert.Null(LlmGoalPolicy.TryResolveExploreLoopedVendor(
            ExploreGoalTo("Blacksmith"), world, es, ExploreVendorSince));
    }

    [Fact]
    public void ExploreLoopedVendor_PartialNameResolvesFuzzily_ResolvesToUseGuid()
    {
        // Under-fire fix (gpt-5.4): the bot loops a PARTIAL name the Motor resolves fuzzily
        // (unique whole-word subsequence) to the full wire name. The rewrite must use the
        // SAME fuzzy semantics, or a fuzzy-resolved loop gets neither the cue nor the rewrite.
        var world = WorldWithVisible(VendorObj(0x7A9B4026u, "Sedor Wystan the Blacksmith"));
        var es = ExploreEmissionsTo("Blacksmith", 3);
        Assert.Equal(0x7A9B4026u, LlmGoalPolicy.TryResolveExploreLoopedVendor(
            ExploreGoalTo("Blacksmith"), world, es, ExploreVendorSince));
    }

    [Fact]
    public void ExploreLoopedVendor_AliasesForSameVendorAccumulate_ResolvesToUseGuid()
    {
        // Identity-count: aliases that bind the SAME vendor accumulate toward the loop
        // threshold (2 partial + 1 full = 3 toward one vendor guid).
        var world = WorldWithVisible(VendorObj(0x7A9B4026u, "Sedor Wystan the Blacksmith"));
        var es = ExploreEmissionsTo("Blacksmith", 2);
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
            Text = "Explore target=name=\"Sedor Wystan the Blacksmith\" item= source=llm:test",
        });
        Assert.Equal(0x7A9B4026u, LlmGoalPolicy.TryResolveExploreLoopedVendor(
            ExploreGoalTo("Sedor Wystan the Blacksmith"), world, es, ExploreVendorSince));
    }

    [Fact]
    public void WieldGroundWeapon_TwoSameNamedGroundWeapons_DoesNotRewrite()
    {
        // Ambiguous: an exact-name selector matches TWO ground weapons. The Motor
        // must NOT autonomously pick one -- stay unresolved so the LLM re-decides.
        var world = WorldWithVisible(
            GroundMeleeWeapon(0xABCu, "Dagger"),
            GroundMeleeWeapon(0xABDu, "Dagger"));
        Assert.Null(LlmGoalPolicy.TryResolveWieldGroundWeapon(
            WieldGoalTo("Dagger"), world, new EventStream()));
    }

    [Fact]
    public void WieldGroundWeapon_NameContainsMatchingMultiple_DoesNotRewrite()
    {
        // A generic name_contains selector (e.g. "weapon") matching multiple ground
        // weapons is ambiguous -> no autonomous selection.
        var world = WorldWithVisible(
            GroundMeleeWeapon(0xABCu, "Iron Weapon"),
            GroundMeleeWeapon(0xABDu, "Bronze Weapon"));
        var goal = new Goal
        {
            Kind = GoalKind.Wield,
            Target = new Selector { NameContains = "Weapon" },
        };
        Assert.Null(LlmGoalPolicy.TryResolveWieldGroundWeapon(goal, world, new EventStream()));
    }

    // ---- IsRaiseOfUntrainedSkill (drop a RaiseSkill of an untrained skill) ----

    private static WorldStateProjection WorldWithTrainedSkillNames(params string[] names)
        => new()
        {
            Self = new SelfProjection
            {
                Guid = 0x500u, Name = "H", HealthFraction = 1.0f,
                TrainedSkills = names.Length == 0
                    ? null
                    : names.Select(n => new SelfSkillProjection
                        { Name = n, Advancement = "trained", RaisedRanks = 0 }).ToArray(),
            },
            Inventory = System.Array.Empty<InventoryItemProjection>(),
            Visible = System.Array.Empty<VisibleObjectProjection>(),
        };

    private static Goal RaiseSkillGoalTo(string skillName)
        => new() { Kind = GoalKind.RaiseSkill, Target = new Selector { Name = skillName } };

    [Fact]
    public void IsRaiseOfUntrainedSkill_UntrainedSkill_True()
    {
        var world = WorldWithTrainedSkillNames("UnarmedCombat", "MeleeDefense");
        Assert.True(LlmGoalPolicy.IsRaiseOfUntrainedSkill(
            RaiseSkillGoalTo("TwoHandedCombat"), world));
    }

    [Fact]
    public void IsRaiseOfUntrainedSkill_TrainedSkill_False()
    {
        var world = WorldWithTrainedSkillNames("TwoHandedCombat", "MeleeDefense");
        Assert.False(LlmGoalPolicy.IsRaiseOfUntrainedSkill(
            RaiseSkillGoalTo("TwoHandedCombat"), world));
    }

    [Fact]
    public void IsRaiseOfUntrainedSkill_TrainedSkillNameVariance_False()
    {
        // The resolver strips spaces/case, so "two handed combat" must match the
        // trained "TwoHandedCombat" -> not flagged untrained.
        var world = WorldWithTrainedSkillNames("TwoHandedCombat");
        Assert.False(LlmGoalPolicy.IsRaiseOfUntrainedSkill(
            RaiseSkillGoalTo("two handed combat"), world));
    }

    [Fact]
    public void IsRaiseOfUntrainedSkill_NonRaiseSkillGoal_False()
    {
        var world = WorldWithTrainedSkillNames("UnarmedCombat");
        var raiseAttr = new Goal { Kind = GoalKind.RaiseAttribute, Target = new Selector { Name = "coordination" } };
        Assert.False(LlmGoalPolicy.IsRaiseOfUntrainedSkill(raiseAttr, world));
    }

    [Fact]
    public void IsRaiseOfUntrainedSkill_NoTrainedSkillsList_False()
    {
        // Skills not loaded yet -> do NOT judge (never drop on an unknown list).
        var world = WorldWithTrainedSkillNames();
        Assert.False(LlmGoalPolicy.IsRaiseOfUntrainedSkill(
            RaiseSkillGoalTo("TwoHandedCombat"), world));
    }

    [Fact]
    public void IsRaiseOfUntrainedSkill_UnresolvableSkillName_False()
    {
        // A name that does not resolve to a real skill is a different error -> let
        // the Motor reject it; do not drop here.
        var world = WorldWithTrainedSkillNames("UnarmedCombat");
        Assert.False(LlmGoalPolicy.IsRaiseOfUntrainedSkill(
            RaiseSkillGoalTo("NotASkillName"), world));
    }

    // ---- IsRaiseGoalWithNoSpendableXp (drop a Raise* with no spendable unspent XP) ----

    private static WorldStateProjection WorldWithUnspentXp(long? unspent)
        => new()
        {
            Self = new SelfProjection
            { Guid = 0x500u, Name = "H", HealthFraction = 1.0f, AvailableExperience = unspent },
            Inventory = System.Array.Empty<InventoryItemProjection>(),
            Visible = System.Array.Empty<VisibleObjectProjection>(),
        };

    private static Goal RaiseGoal(GoalKind kind, string target)
        => new() { Kind = kind, Target = new Selector { Name = target } };

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_ZeroUnspent_True_ForAllRaiseKinds()
    {
        // The live loop: a Raise* with unspent=0 cannot be actuated (the Motor refuses).
        var zero = WorldWithUnspentXp(0);
        Assert.True(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseAttribute, "coordination"), zero, 0));
        Assert.True(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseSkill, "TwoHandedCombat"), zero, 0));
        Assert.True(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseVital, "health"), zero, 0));
    }

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_PositiveUnspentAtDefaultFloor_False()
    {
        Assert.False(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseAttribute, "coordination"), WorldWithUnspentXp(100), 0));
    }

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_BelowMeaningfulFloor_True()
    {
        // Sub-floor unspent: the SPEND XP cues are suppressed AND the raise is dropped
        // (consistent with the min-meaningful-unspent-xp floor).
        Assert.True(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseAttribute, "coordination"), WorldWithUnspentXp(30), 50));
    }

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_AtOrAboveFloor_False()
    {
        Assert.False(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseAttribute, "coordination"), WorldWithUnspentXp(60), 50));
    }

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_NonRaiseGoal_False()
    {
        // A non-Raise goal is never dropped by this guard even with no XP.
        var attack = new Goal { Kind = GoalKind.Attack, Target = new Selector { Name = "Rabbit" } };
        Assert.False(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(attack, WorldWithUnspentXp(0), 0));
    }

    [Fact]
    public void IsRaiseGoalWithNoSpendableXp_UnknownUnspent_False()
    {
        // Balance not loaded yet -> do NOT drop (never assume futile on an unknown).
        Assert.False(LlmGoalPolicy.IsRaiseGoalWithNoSpendableXp(
            RaiseGoal(GoalKind.RaiseAttribute, "coordination"), WorldWithUnspentXp(null), 0));
    }

    [Fact]
    public void FormatContractCounts_CountsInProgressAndDoneByStage()
    {
        // Stage codes (ACE ContractTracker): 1 Available, 2 InProgress,
        // 3 DoneOrPendingRepeat, 4+ ProgressCounter (counts as in-progress).
        var contracts = new List<ContractProjection>
        {
            new() { ContractId = 1, Stage = 2u },   // in progress
            new() { ContractId = 2, Stage = 5u },   // 4+ -> in progress
            new() { ContractId = 3, Stage = 3u },   // done
            new() { ContractId = 4, Stage = 3u },   // done
            new() { ContractId = 5, Stage = 1u },   // available (neither p nor d)
        };
        Assert.Equal("5(p2/d2)", LlmGoalPolicy.FormatContractCounts(contracts));
    }

