    [Fact]
    public void IsRepeatedDialogText_DifferentKindSameText_False()
    {
        // A PopupString does not dedup against an NpcDialog with identical text —
        // they are distinct channels of information.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "same" });
        var pop = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "same" });
        Assert.False(LlmGoalPolicy.IsRepeatedDialogText(es, pop));
    }

    [Fact]
    public void IsRepeatedDialogText_RepeatedActionRejected_False()
    {
        // ActionRejected is a fresh action OUTCOME each time, never deduped here —
        // a repeated rejection still interrupts the chain.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected, Text = "no", ErrorCode = 0x046A });
        var dup = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected, Text = "no", ErrorCode = 0x046A });
        Assert.False(LlmGoalPolicy.IsRepeatedDialogText(es, dup));
    }

    [Fact]
    public void IsRepeatedDialogText_SameNpcVerbatimRepeat_True()
    {
        // Same speaker (guid) re-emitting the same line -> a repeat.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "tip", ItemGuid = 0x1234u, Name = "Golem" });
        var dup = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "tip", ItemGuid = 0x1234u, Name = "Golem" });
        Assert.True(LlmGoalPolicy.IsRepeatedDialogText(es, dup));
    }

    [Fact]
    public void IsRepeatedDialogText_DifferentNpcSameText_False()
    {
        // A DIFFERENT speaker's first identical line is NOT a repeat — it still
        // interrupts so a new NPC interaction reaches the LLM.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "hello", ItemGuid = 0x1111u, Name = "Guard A" });
        var other = es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "hello", ItemGuid = 0x2222u, Name = "Guard B" });
        Assert.False(LlmGoalPolicy.IsRepeatedDialogText(es, other));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_TwoIdenticalAboveFloor_InterruptsExactlyOnce()
    {
        // Two verbatim popups both ARRIVED since the floor: the newest is a repeat
        // (skipped), but the first occurrence still interrupts -> the scan reports
        // the kind exactly once rather than swallowing both.
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "loot tip" });
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.PopupString, Text = "loot tip" });
        Assert.Equal(EventKind.PopupString, LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void IsChainInterruptingEvent_TransportFailureActionRejected_DoesNotInterrupt()
    {
        // cp025: a transport-failure rejection (the Motor could not reach/resolve
        // the target — it stopped resolving) is a benign routing outcome; the
        // decomposition should advance to its next matching target, not force an
        // LLM call.
        var e = new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = 0xFFFEu, ErrorLabel = "Unreachable",
        };
        Assert.False(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_SemanticActionRejected_StillInterrupts()
    {
        // A semantic (non-transport) rejection — a real action refusal or a
        // self-preservation disengage — IS decision-worthy and still interrupts.
        var e = new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = 0x046Au, ErrorLabel = "TradeAiDoesntWant",
        };
        Assert.True(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_NpcDialog_StillInterrupts()
    {
        var e = new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.NpcDialog, Text = "hi" };
        Assert.True(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_NonInterruptingKind_DoesNotInterrupt()
    {
        var e = new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ServerMessage, Text = "you have slain a foe" };
        Assert.False(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_LandblockChanged_DoesNotInterrupt()
    {
        // cp029: crossing a cell boundary mid-grind is not itself decision-worthy
        // for the kill-count chain — ChooseCombatChainTarget's visible-target filter
        // already yields (no-matching-monster) when the committed kind is absent in
        // the new area, while if the same kind is still visible the grind simply
        // continued across the boundary. So LandblockChanged no longer preempts the
        // chain (bounded by the MaxCombatChainAttacks cap + the 0xFFFB disengage,
        // which still interrupts). The kind, event, and scan helpers all agree.
        var e = new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.LandblockChanged };
        Assert.False(LlmGoalPolicy.IsChainInterruptingKind(EventKind.LandblockChanged));
        Assert.False(LlmGoalPolicy.IsChainInterruptingEvent(e));
        var es = new EventStream();
        es.Append(e);
        Assert.Null(LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void IsChainInterruptingEvent_AttackLoopCancelActionRejected_DoesNotInterrupt()
    {
        // The SURFACED combat swing-loop cancel carries the Motor-reserved code
        // (0xFFFA) — the Motor handles it itself (an immediate attack re-send),
        // so while a kill-count decomposition is running it names no
        // LLM-actionable problem and must NOT preempt the chain with a round-trip.
        var e = new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = CombatRetry.SurfacedSwingLoopCancelCode, ErrorLabel = "ActionCancelled",
        };
        Assert.False(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_RawInventoryActionCancel_StillInterrupts()
    {
        // The RAW ActionCancelled wire code (0x0036) also rides on inventory
        // ActionCancelled rejections (InventoryServerSaveFailed) — those are
        // decision-worthy and must STILL interrupt. Only the surfaced COMBAT
        // cancel (the Motor-reserved code) is benign, so a raw 0x0036 event must
        // not be mistaken for it.
        var e = new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = CombatRetry.AttackDoneActionCancelled, ErrorLabel = "ActionCancelled",
            ItemGuid = 0x80000001u, Name = "some item",
        };
        Assert.NotEqual(CombatRetry.AttackDoneActionCancelled, CombatRetry.SurfacedSwingLoopCancelCode);
        Assert.True(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void IsChainInterruptingEvent_DangerDisengageActionRejected_StillInterrupts()
    {
        // The Motor's self-preservation disengage carries a reserved code that is
        // neither a transport failure (0xFFFC-0xFFFE) nor the swing-loop cancel
        // (0xFFFA), so it stays a decision-worthy interrupt. This is the safety
        // guarantee cp025 established — it must survive the cancel-code exclusion.
        var e = new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = 0xFFFBu, ErrorLabel = "DisengageLowHealth",
        };
        Assert.True(LlmGoalPolicy.IsChainInterruptingEvent(e));
    }

    [Fact]
    public void FirstChainInterruptingKindSince_SkipsTransportFailureActionRejected()
    {
        // The transport-failure ActionRejected must NOT be reported as an
        // interrupter (so the chain keeps minting through it).
        var es = new EventStream();
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ActionRejected,
            ErrorCode = 0xFFFEu, ErrorLabel = "Unreachable",
        });
        Assert.Null(LlmGoalPolicy.FirstChainInterruptingKindSince(es, 0));
    }

    [Fact]
    public void StreamEvent_HeardSpeech_ToString_RendersSpeakerAndLine()
    {
        var e = new StreamEvent
        {
            Sequence = 7,
            Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.HeardSpeech,
            Name = "Nearby Speaker",
            Text = "a spoken line",
        };
        var s = e.ToString();
        Assert.Contains("HeardSpeech from=\"Nearby Speaker\"", s);
        Assert.Contains("a spoken line", s);
    }

    [Fact]
    public void AppendHeardSpeech_StaysOutOfMainRing_SoItCannotEvictCriticalEvents()
    {
        // Ambient heard speech must NEVER enter the bounded main event ring —
        // a flood of it would otherwise evict ActionRejected / GoalFailed memory
        // (the prompt looks back ~100 events) and could strand the bot in a
        // retry loop. It is segregated into a dedicated window instead.
        var stream = new EventStream();
        stream.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.ActionRejected, ErrorLabel = "Blocked",
        });
        stream.AppendHeardSpeech(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.HeardSpeech, Name = "Nearby Speaker", Text = "a spoken line",
        });

        // The main ring retains the critical rejection and is NOT polluted by
        // the ambient speech.
        Assert.Contains(stream.Recent(), e => e.Kind == EventKind.ActionRejected);
        Assert.DoesNotContain(stream.Recent(), e => e.Kind == EventKind.HeardSpeech);
        // The dedicated window holds the heard speech.
        Assert.Contains(stream.RecentHeardSpeech(), e => e.Kind == EventKind.HeardSpeech);
    }

    private static StreamEvent MakeHeard(string text) => new()
    {
        Sequence = -1,
        Utc = DateTimeOffset.UtcNow,
        Kind = EventKind.HeardSpeech,
        Name = "Speaker",
        Text = text,
    };

    [Fact]
    public void BuildUserPrompt_HeardSpeech_KeepsRecentlyRespokenLineOverOlderDistinctLines()
    {
        // Dedup must keep the NEWEST occurrence of a repeated line so a just-
        // respoken line is treated as recent by RetainEnds. With >6 distinct
        // lines and one respoken last, dedup-by-OLDEST would retain the stale
        // first-seen sequence and RetainEnds(2,4) would drop it (regression).
        var stream = new EventStream();
        foreach (var t in new[] { "A", "B", "C", "D", "E", "F", "G" })
            stream.AppendHeardSpeech(MakeHeard(t));
        stream.AppendHeardSpeech(MakeHeard("C")); // C is the most-recently heard line

        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildImmobileWorld(0), stream, null);

        Assert.Contains("HeardSpeech from=\"Speaker\": \"C\"", prompt);
    }

