            Inventory = new[] { new InventoryItemProjection { Guid = 0x7E1u, Name = "Spadone", Wcid = 1u, ItemType = 0x1u, WieldedAt = 0x02000000u } },
        };
        var prompt = LlmGoalPolicy.BuildUserPrompt(
