        var es = new EventStream();
        es.Append(ExploreEmission("Wayfarer"));
        var world = BuildVisibleWorld(NamedVisible("Wayfarer", 40f));

        Assert.False(LlmGoalPolicy.TryDetectReachedExploreTarget(world, es, out _, out _));
    }

