        var world = BuildVisibleWorld(NamedVisible("Wayfarer", 2f));
        var goal = new Goal { Kind = GoalKind.Explore, Target = new Selector { Name = "Stonekeeper" } };

        Assert.False(LlmGoalPolicy.IsExploreToReachedTarget(goal, world));
