            Name = "Central Courtyard",
        });
        var prompt = LlmGoalPolicy.BuildUserPrompt(BuildVisibleWorld(), es, null);
        Assert.Contains("## Explore loop (unresolved target)", prompt);
        Assert.DoesNotContain("being REFUSED as unreachable", prompt);
        Assert.Contains("keep `Explore`-ing toward it", prompt);
    }

    private static EventStream AttackEmissions(string name, int count, System.DateTimeOffset utc)
    {
        var es = new EventStream();
        for (int i = 0; i < count; i++)
            es.Append(new StreamEvent
            {
                Sequence = -1, Utc = utc, Kind = EventKind.GoalEmitted,
                Text = $"Attack target=name=\"{name}\" item= source=llm:test",
            });
        return es;
    }

    [Fact]
    public void RepeatedUnresolvedAttackTarget_ReturnsNameForRepeatedNoVisibleMatch()
    {
        // 3 recent Attack emissions toward a name with NO matching visible object -> the
        // looped target (a monster the bot has travelled past / that died). The capsule
        // cues the LLM; it does NOT drop the goal.
        var now = System.DateTimeOffset.UtcNow;
        var world = BuildVisibleWorld(NamedVisible("Drudge", 5f)); // some other monster, NOT the name
        var es = AttackEmissions("The Chicken", 3, now);
        Assert.Equal("The Chicken", LlmGoalPolicy.RepeatedUnresolvedAttackTarget(world, es, now.AddMinutes(-3)));
    }

    [Fact]
    public void RepeatedUnresolvedAttackTarget_AccumulatesRoleSuffixedAndBareUnderBareName()
    {
        // A model that alternates `The Chicken` and the rendered `The Chicken "Hen"` label
        // for the SAME departed target must accumulate under one bare key: 2 bare + 1
        // role-suffixed = 3 >= threshold, so the loop cue fires (previously the suffixed
        // spelling keyed a separate bucket and neither bucket reached the threshold).
        var now = System.DateTimeOffset.UtcNow;
        var world = BuildVisibleWorld(NamedVisible("Drudge", 5f)); // not the looped name
        var es = new EventStream();
        foreach (var nm in new[] { "The Chicken", "The Chicken", "The Chicken \"Hen\"" })
            es.Append(new StreamEvent
            {
                Sequence = -1, Utc = now, Kind = EventKind.GoalEmitted,
                Text = $"Attack target=name=\"{nm}\" item= source=llm:test",
            });
        Assert.Equal("The Chicken", LlmGoalPolicy.RepeatedUnresolvedAttackTarget(world, es, now.AddMinutes(-3)));
    }

