        var es = PickupEmissions("name_contains=\"dagger\"", 3, now);
        Assert.Equal("dagger",
            LlmGoalPolicy.RepeatedDescriptorPickup(BuildVisibleWorld(), es, now.AddMinutes(-3)));
    }

