    [Fact]
    public void BuildUserPrompt_UntalkedNpcsCapsule_SurvivesBodyTrimAtTinyCeiling()
    {
        // The capsule lives in the protected salience tail, so a far not-yet-
        // talked NPC stays visible by name even at a tight request ceiling that
        // forces the trimmable `## Visible nearby` body section to be shed.
        var near = NearTalkedNpcs(25);
        var farUntalked = CivilianNpc(0x800000FFu) with { Distance = 80f };
        var world = BuildVisibleWorld(near.Append(farUntalked).ToArray());
        var talked = new HashSet<uint>(near.Select(n => n.Guid));

        var prompt = LlmGoalPolicy.BuildUserPrompt(
            world, new EventStream(), currentGoal: null, stack: null,
            pickerActivity: null, explorationCandidates: null,
            talkedNpcGuids: talked, promptCeiling: 10000);

        Assert.Contains("## Untalked NPCs nearby", prompt);
        Assert.Contains("Npc 800000FF", CapsuleSection(prompt, "## Untalked NPCs nearby"));
        Assert.True(prompt.Length <= 10000, $"prompt length {prompt.Length} exceeds ceiling 10000");
    }

    [Fact]
    public void BuildUserPrompt_ContractsCapsule_SurvivesBodyTrimAtTinyCeiling()
    {
        // The ## Contracts section lives in the protected salience tail, so a
        // tracked objective (what it requires / who turns it in) stays visible
        // even at a tight request ceiling that forces the trimmable body (rules
        // preamble + ## Visible nearby) to be hard-cut. Regression guard: it
        // previously rendered mid-body and was guillotined before the LLM saw it
        // (the cp2889 enrichment was effectively invisible live).
        var world = BuildEnrichedContractWorld(
            new ContractProjection
            {
                ContractId = 700u, Stage = 1u,
                Name = "Slay the Drudges",
                Description = "Defeat 5 drudges in the mine and report back.",
                NpcEnd = "Sergeant",
            });

        var prompt = LlmGoalPolicy.BuildUserPrompt(
            world, new EventStream(), currentGoal: null, stack: null,
            pickerActivity: null, explorationCandidates: null,
            talkedNpcGuids: new HashSet<uint>(), promptCeiling: 10000);

        Assert.Contains("## Contracts", prompt);
        var cap = CapsuleSection(prompt, "## Contracts");
        Assert.Contains("contract 700 \"Slay the Drudges\"", cap);
        Assert.Contains("objective: Defeat 5 drudges", cap);
        Assert.Contains("turn-in NPC: Sergeant", cap);
        Assert.True(prompt.Length <= 10000, $"prompt length {prompt.Length} exceeds ceiling 10000");
    }

    [Fact]
    public void BuildUserPrompt_ContractsCapsule_CharBudgetCapsAndNotesOverflow()
    {
        // Many contracts with long objective text must not let the protected
        // capsule blow its char budget: excess contracts are dropped (in wire
        // order) with a "+N more" note, and the first contract always survives.
        var many = Enumerable.Range(0, 20)
            .Select(i => new ContractProjection
            {
                ContractId = (uint)(1000 + i),
                Stage = 2u,
                Name = $"Contract Number {i}",
                Description = new string('x', 180),
                NpcEnd = "Giver",
            })
            .ToArray();
        var world = BuildEnrichedContractWorld(many);

        var prompt = LlmGoalPolicy.BuildUserPrompt(world, new EventStream(), null);
        var cap = CapsuleSection(prompt, "## Contracts");

        Assert.Contains("## Contracts", prompt);
        Assert.Contains("contract 1000", cap);              // first always survives
        Assert.Contains("more tracked, not shown)", cap);   // overflow noted
        var rendered = System.Text.RegularExpressions.Regex.Matches(cap, @"- contract \d+").Count;
        Assert.True(rendered is >= 1 and < 20,
            $"char budget should drop some of 20 contracts but keep >=1; rendered {rendered}");
    }

    // Returns the text of a `## `-headed section: from the header up to the
    // next `## ` header (or end of prompt). Bounds Contains assertions to the
    // intended capsule so a name appearing in a later section can't pass.
    private static string CapsuleSection(string prompt, string header)
    {
        int start = prompt.IndexOf(header, StringComparison.Ordinal);
        if (start < 0) return string.Empty;
        int next = prompt.IndexOf("\n## ", start + header.Length, StringComparison.Ordinal);
        return next < 0 ? prompt.Substring(start) : prompt.Substring(start, next - start);
    }

    [Fact]
    public async Task LlmGoalPolicy_TalkedNpcPersistsAfterEmissionAgesOut()
    {
        // Production LLM Talk goals are NAME-ONLY (Selector.Guid is null and the
        // Motor's resolved guid is never written back into the emitted Goal), so
        // the session talked-set must persist by NAME. Use a name-only emission
        // whose name matches the visible NPC and assert it stays "talked" even
        // after the emission ages out of the bounded event ring.
        var requestBodies = new List<string>();
        var canned = JsonSerializer.Serialize(new
        {
            choices = new[] { new { message = new { content = "{\"kind\":\"Explore\",\"target\":{\"name\":\"anywhere\"},\"rationale\":\"x\",\"priority\":3}" } } },
        });
        var http = new HttpClient(new AsyncStubHandler(async (req, ct) =>
        {
            var body = req.Content is null ? "" : await req.Content.ReadAsStringAsync(ct);
            requestBodies.Add(body);
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(canned) };
        }));
        var policy = new LlmGoalPolicy(
            new LlmGoalClient(http, "https://test.example/chat", "test-model", "key"),
            new NoQuestKnowledgePolicy(),
            new InMemoryWeenieRepo())
        {
            MinCallInterval = TimeSpan.Zero,
        };
        var events = new EventStream();
        events.Append(new StreamEvent
        {
            Sequence = -1,
            Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.GoalEmitted,
            Text = "Talk target=name=\"Npc 90000001\" item=<empty> source=llm:test",
        });

        var world = BuildVisibleWorld(CivilianNpc(0x90000001u));
        Assert.Null(policy.ProposeGoal(world, events, null));
        await policy.WaitForInFlightAsync();
        var firstGoal = policy.ProposeGoal(world, events, null);
        Assert.NotNull(firstGoal);

        Assert.Single(requestBodies);
        Assert.Contains("- untalked npcs in view: 0", PromptFromRequest(requestBodies[0]));

        for (var i = 0; i < EventStream.DefaultCapacity + 20; i++)
        {
            events.Append(new StreamEvent
            {
                Sequence = -1,
                Utc = DateTimeOffset.UtcNow,
                Kind = EventKind.ServerMessage,
                Text = $"ambient event {i}",
            });
        }
        events.Append(new StreamEvent
        {
            Sequence = -1,
            Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.ActionRejected,
            ErrorLabel = "Blocked",
            Text = "test",
        });

        _ = policy.ProposeGoal(world, events, firstGoal);
        await policy.WaitForInFlightAsync();

        Assert.Equal(2, requestBodies.Count);
        Assert.Contains("- untalked npcs in view: 0", PromptFromRequest(requestBodies[1]));
    }

    private static string PromptFromRequest(string requestBody)
    {
        using var doc = JsonDocument.Parse(requestBody);
        return doc.RootElement
            .GetProperty("messages")[1]
            .GetProperty("content")
            .GetString()!;
    }

    [Fact]
    public void TryParseGoal_ParsesRaiseAttributeWithAmount()
    {
