    [Fact]
    public void LlmGoalPolicy_Prompt_SpendXpRuleCarriesFullAttributeMechanics()
    {
        // Regression guard for the spend-xp-attribute-balance slice. Live
        // evidence (a level-9 bot at strength 10 / endurance 49 / everything
        // else 10) showed the LLM pouring ALL its XP into endurance — the only
        // attribute the old SPEND XP rule explained or exemplified — leaving it
        // tanky but unable to land melee hits, so it lost fights of attrition
        // and died. The fix surfaces the FULL attribute->effect mechanics as
        // FACTS so the LLM can balance, and drops the single endurance-anchoring
        // worked example. These assertions lock that in.
        // unspent XP > 0 so the (now unspent-gated) SPEND XP rule renders; this
        // test guards the rule's CONTENT, not its render condition.
        var world = BuildXpWorld(69296, 5475);
        var events = new EventStream();
        var prompt = LlmGoalPolicy.BuildUserPrompt(world, events, null);

        // The SPEND XP rule is still present with all three raise verbs.
        Assert.Contains("SPEND XP", prompt);
        Assert.Contains("RaiseAttribute", prompt);
        Assert.Contains("RaiseVital", prompt);
        Assert.Contains("RaiseSkill", prompt);

        // Offensive + utility mechanics are now stated as facts, not just the
        // defensive endurance->MAX HEALTH mechanic. Strength is the DAMAGE
        // (HARD) lever; coordination + trained weapon skill are the ACCURACY
        // (LAND) levers — stated without conflation so the LLM does not raise
        // strength for a miss/evade problem.
        Assert.Contains("strength PRIMARILY drives DAMAGE", prompt);
        Assert.Contains("are your PRIMARY ACCURACY levers (how OFTEN your swings LAND)", prompt);
        // cp2911: the trained weapon SKILL is now surfaced as a primary melee-
        // offense lever (live: the bot raised attributes 10x but RaiseSkill 0x).
        Assert.Contains("TRAINED WEAPON SKILL you fight with", prompt);
        Assert.Contains("focus and self power magic", prompt);
        Assert.Contains("quickness aids defense and missile play", prompt);
        Assert.Contains("endurance and health raise MAX HEALTH", prompt);

        // Anti-tunnel-vision + adaptive-allocation guidance (no fixed build).
        Assert.Contains("there is NO fixed build", prompt);
        Assert.Contains("Do NOT pour every point into ONE attribute", prompt);

        // The single endurance-anchoring worked example is gone: the
        // RaiseAttribute verb now uses a neutral <attribute> placeholder.
        Assert.Contains("RaiseAttribute{target: {name: \"<attribute>\"}", prompt);
        Assert.DoesNotContain("RaiseAttribute{target: {name: \"endurance\"}", prompt);

        // cp2912: the RaiseSkill verb now hard-guards the target. Live evidence
        // (a melee bot with unspent XP but no `trained skills` list surfaced)
        // showed the LLM passing its WIELDED WEAPON's item name to RaiseSkill 5x
        // in a row; the motor rejected each as an unknown skill. The verb text
        // must forbid a weapon ITEM name and forbid RaiseSkill entirely when no
        // `trained skills` list is present, so a missing projection can never
        // drive that loop.
        Assert.Contains("NEVER a weapon ITEM's name", prompt);
        Assert.Contains("if `## Self` shows NO `trained skills` list, do NOT use `RaiseSkill`", prompt);
    }

    [Fact]
    public void LlmGoalPolicy_SpendXp_SeparatesDamageLeverFromAccuracyLever()
    {
        // cp2926-followup: live (mistral-small, char with coordination 10 /
        // strength 47, swings evading ~84%) the bot poured its WHOLE XP balance
        // into strength 37x — rationale "Strength is the main driver of melee
        // damage" — while its swings kept MISSING. The old rule conflated the
        // two ("strength and coordination drive MELEE offense (how hard and how
        // often your swings land)"; "raise coordination/strength when melee
        // swings miss or barely hurt"), giving the LLM cover to raise the DAMAGE
        // lever for a MISS problem. The corrected rule attributes strength
        // PRIMARILY to damage (not the main accuracy lever) and maps the
        // evade/miss symptom to coordination + the trained weapon skill, while
        // still mapping a landed-but-low-damage swing to strength.
        var world = BuildXpWorld(69296, 5475);
        var prompt = LlmGoalPolicy.BuildUserPrompt(world, new EventStream(), null);

        // Strength is PRIMARILY the DAMAGE lever and not the main accuracy lever.
        Assert.Contains("strength PRIMARILY drives DAMAGE", prompt);
        Assert.Contains("is NOT your main accuracy lever", prompt);

        // Coordination + trained weapon skill are the ACCURACY (LAND) levers.
        Assert.Contains("are your PRIMARY ACCURACY levers (how OFTEN your swings LAND)", prompt);

        // The evade/miss symptom prioritizes accuracy levers OVER strength (the
        // weapon-skill lever is qualified to the wielded weapon — cp056).
        Assert.Contains("the limit is ACCURACY \u2014 PRIORITIZE coordination and your trained weapon skill (your accuracy levers; the weapon skill only when it governs your WIELDED weapon \u2014 see the `wielded-weapon accuracy` note) over strength", prompt);

        // A landed-but-low-damage swing still maps to strength (no over-correction).
        Assert.Contains("if your swings LAND but deal 0/low `damage`, the limit is strength", prompt);

        // The old conflations AND the survivor conflations are gone.
        Assert.DoesNotContain("strength and coordination drive MELEE offense", prompt);
        Assert.DoesNotContain("coordination/strength", prompt);
        Assert.DoesNotContain("and strength (so they HURT)", prompt);
    }

    [Fact]
    public void LlmGoalPolicy_Prompt_SchemaDeclaresExploreDirectionField()
    {
        // cp-2351 added the Explore `direction` parser + Motor wiring and a prose
        // STEER A BARREN EXCURSION rule, but never declared `direction` in the
        // output JSON schema — and the prompt says "no extra fields", so the LLM
        // (obeying the schema) could not emit it (live: 0 directional Explores
        // across runs despite the rule rendering, the bot oscillating near the
        // safe zone). Declaring it in the schema unblocks the field. Guard it.
        var world = BuildXpWorld(69296, 0);
        var events = new EventStream();
        var prompt = LlmGoalPolicy.BuildUserPrompt(world, events, null);

        Assert.Contains("\"direction\":", prompt);   // declared field
        Assert.Contains("\"northwest\"", prompt);    // the 8-way compass enum
        Assert.Contains("Explore only", prompt);     // scoped to the Explore verb
        // Schema documents the full accepted set, matching TryHeadingVector
        // (which also accepts the n/ne/.../nw abbreviations).
        Assert.Contains("short forms n/ne/e/se/s/sw/w/nw also accepted", prompt);
    }

    [Fact]
    public void SurvivabilityCheck_RendersWhenDiedThisSession_AndUnspentXp()
    {
        // Survivability-spend salience: when the bot has died this session
        // (secondsSinceLastDeath set) AND has unspent XP, `## Self` surfaces a pointer to
        // raise ENDURANCE/health first — elevating the SPEND XP rule's dying->max-HP
        // tiebreaker that a capable model buries while pouring XP into offense.
