        var goal = new Goal
        {
            Kind = GoalKind.Give,
            Target = new Selector { Name = "Worcer" },
            Item = new Selector { Name = "A List of Items" },
        };
        Assert.True(LlmGoalPolicy.IsGoalRecentlyRejected(goal, es));
    }

