        var fellow = new FellowshipProjection
        {
            Name = "Crew", AmLeader = true, LeaderName = "Headless", MemberCount = 1,
            Members = new[]
            {
                new FellowshipMemberProjection { Name = "Headless", Level = 10u, IsSelf = true, IsLeader = true },
            },
