                { Guid = 0x222u, Name = "Throwing Knife", Wcid = 999u, ItemType = 0x100u, ValidLocations = 0x400000u, WieldedAt = null, AmmoType = null },
                // Bag ammo that would be WRONGLY paired with the knife if it counted as a launcher.
