        AppendNoLiveObjectFail(es, "Corpse of Chicken", kind: "Pickup");
        var world = BuildWorldWithVisible();
        Assert.False(LlmGoalPolicy.IsUnreachableTargetRepeat(
            PickupGoalNamed("Corpse of Chicken"), world, es));
    }

