    [Fact]
    public void IsUnreachableTargetRepeat_OutOfReach_MultipleVisibleSameName_StillDrops()
    {
        // Design note (gpt-5.4 review): the name-level drop fires EVEN when several
        // same-named objects are visible. Pickup/Use resolution picks the NEAREST match
        // and the Motor only nulls it when suppressed — it never falls through to a
        // farther sibling — so a nearer out-of-reach instance keeps the loop alive
        // while the name is re-emitted. Dropping the name and Exploring (which moves
        // the bot, changing which instance is nearest) is the correct escape.
        var es = new EventStream();
        AppendOutOfReachFail(es, "Apple");
        AppendOutOfReachFail(es, "Apple");
        var world = BuildWorldWithVisible(
            new VisibleObjectProjection { Guid = 0x90000051u, Name = "Apple", ItemType = 0x2u, Distance = 1.0f },
            new VisibleObjectProjection { Guid = 0x90000052u, Name = "Apple", ItemType = 0x2u, Distance = 7.0f });
        Assert.True(LlmGoalPolicy.IsUnreachableTargetRepeat(
            PickupGoalNamed("Apple"), world, es));
    }

    // ---- IsLowHealthDeferredAttackRepeat (cp040): the Motor refuses to walk an
    //      Attack into melee while self-health is below the re-engage threshold; a
    //      weak model re-emits Attack every cycle, burning LLM calls instead of
    //      recovering. After >=2 such deferrals the caller substitutes an Explore
    //      egress to leave the fight and regen. ----

    private static void AppendLowHealthDeferFail(EventStream es, string targetName = "Drudge")
        => es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.GoalFailed, GoalId = Guid.NewGuid(),
            Name = targetName,
            // Mirrors HandshakeDriver's low-health Attack-defer Fail reason verbatim,
            // wrapped in the TacticsExecutor "{Kind}: {reason}" envelope.
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_TwoDeferrals_True()
    {
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        Assert.True(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_OneDeferral_False()
    {
        // A single defer is normal (recover one tick); only a sustained loop egresses.
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        Assert.False(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_DeferralsAcrossDifferentTargets_StillCounts()
    {
        // The defer is about the BOT's health, not a specific target — re-targeting a
        // different monster while low-health still counts toward the egress.
        var es = new EventStream();
        AppendLowHealthDeferFail(es, "Drudge Skulker");
        AppendLowHealthDeferFail(es, "Mite Scion");
        Assert.True(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_OtherFailsDoNotCount()
    {
        // The no-live-object / out-of-reach failures are a DIFFERENT signal and must
        // not trip the low-health egress.
        var es = new EventStream();
        AppendNoLiveObjectFail(es, "Drudge", kind: "Attack");
        AppendNoLiveObjectFail(es, "Drudge", kind: "Attack");
        AppendOutOfReachFail(es, "Apple");
        AppendOutOfReachFail(es, "Apple");
        Assert.False(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_EmptyStream_False()
    {
        Assert.False(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(new EventStream()));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_SurvivesRingEvictionByPerceptionTraffic()
    {
        // The regression this fix targets: two combat-defer refusals land on SEPARATE
        // decisions ~tens of seconds apart, with hundreds of perception/motion events
        // between them, so the first was evicted from the 256-event ring before the
        // second arrived — events.Recent(N) then saw only ONE and the egress never fired,
        // so the bot looped a refused Attack. Reading the DURABLE GoalFailed window keeps
        // both, so a real loop is detected.
        var es = new EventStream();
        var t0 = new DateTimeOffset(2026, 6, 24, 12, 0, 0, TimeSpan.Zero);
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0, Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });
        for (int i = 0; i < 400; i++)
            es.Append(new StreamEvent { Sequence = -1, Utc = t0.AddSeconds(20), Kind = EventKind.HealthChanged });
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0.AddSeconds(40), Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });

        // now = t0+40s: both defers (t0 and t0+40s) are within the 90s recency window.
        Assert.True(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es, t0.AddSeconds(40)));
        // The first defer is indeed gone from the perception-dominated ring (the old
        // window) — proving the durable read is what carries it.
        Assert.Equal(1, es.Recent(EventStream.DefaultCapacity).Count(e => e.Kind == EventKind.GoalFailed));
    }

    [Fact]
    public void IsLowHealthDeferredAttackRepeat_StaleDefersOutsideRecency_NoAppend_False()
    {
        // Two defers, then the wall clock advances past the recency window with NO new
        // event appended (a timer-driven re-deliberation re-reads history). The durable
        // window still holds them, but they are no longer a CURRENT loop -> false, so the
        // egress does NOT convert a later (post-recovery) Attack to Explore for the whole
        // 30-min durable retention.
        var es = new EventStream();
        var t0 = new DateTimeOffset(2026, 6, 24, 12, 0, 0, TimeSpan.Zero);
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0, Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0.AddSeconds(1), Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });
        Assert.True(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es, t0.AddSeconds(2)));  // current loop
        // Wall clock +3 min with NO append (the real-clock cutoff, not a stale event proxy).
        Assert.False(LlmGoalPolicy.IsLowHealthDeferredAttackRepeat(es, t0.AddMinutes(3))); // resolved -> no over-fire
    }

    // ---- SUSTAIN-COMBAT CHECK (fragile-flee-raise-hp): the prompt cue that fires
    //      when the bot repeatedly FLEES low-health combat (deferred attacks) with
    //      unspent XP and is NOT in a recent-death / death-spiral state. ----

    [Fact]
    public void SustainCombatCheck_RendersWhenFleeingWithUnspentXp()
    {
        // Repeated low-health attack deferrals + unspent XP + no recent death + not
        // spiraling -> the cue surfaces the FLEE pattern and points at BOTH levers
        // (max HP if winning-but-slow, offense if missing), deferring to the bot's
        // evidence so it never contradicts the SPEND XP "survive-but-cannot-kill ->
        // offense" guidance.
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 5475), es, null, null, null, null,
            secondsSinceLastDeath: null, recentOwnDeathCount: 0);
        Assert.Contains("SUSTAIN-COMBAT CHECK", prompt);
        Assert.Contains("ENDURANCE/health", prompt);
        // Balanced, evidence-based: it must NOT categorically claim max HP is the limit;
        // it names the offense alternative so it cannot mis-steer an offense-limited fight.
        Assert.Contains("OFFENSE is the limit", prompt);
        // Lock in the round-1 fix: the old categorical claim must not return.
        Assert.DoesNotContain("MAX HP is the binding limit", prompt);
    }

    [Fact]
    public void SustainCombatCheck_AbsentWhenDeferralsAgeOut()
    {
        // The deferral signal is the DURABLE GoalFailed window scoped to a short recency
        // window (eviction-resistant, but only a CURRENT loop counts). Two defers followed
        // by enough TIME (a later event past the recency window) must NOT keep the cue
        // latched (it is a CURRENT-fragility cue, not a stale-history one).
        var es = new EventStream();
        var t0 = new DateTimeOffset(2026, 6, 24, 12, 0, 0, TimeSpan.Zero);
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0, Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });
        es.Append(new StreamEvent
        {
            Sequence = -1, Utc = t0.AddSeconds(1), Kind = EventKind.GoalFailed,
            Text = "Attack: combat deferred: self-health too low to re-engage — recover before attacking",
        });
        // Advance "now" (the newest stream event) well past the recency window with only
        // perception traffic -> the stale defers fall outside the window.
        es.Append(new StreamEvent { Sequence = -1, Utc = t0.AddMinutes(3), Kind = EventKind.HealthChanged });
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 5475), es, null, null, null, null,
            secondsSinceLastDeath: null, recentOwnDeathCount: 0);
        Assert.DoesNotContain("SUSTAIN-COMBAT CHECK", prompt);
    }

    [Fact]
    public void SustainCombatCheck_AbsentWhenNotFleeing()
    {
        // No low-health deferrals -> not the fragile-flee state -> no cue.
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 5475), new EventStream(), null, null, null, null,
            secondsSinceLastDeath: null, recentOwnDeathCount: 0);
        Assert.DoesNotContain("SUSTAIN-COMBAT CHECK", prompt);
    }

    [Fact]
    public void SustainCombatCheck_AbsentWhenRecentDeath_SurvivabilityFirstOwnsIt()
    {
        // A recent death routes to SURVIVABILITY-FIRST CHECK (the else-if yields), so the
        // flee cue must NOT also fire (no double survivability steer).
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 5475), es, null, null, null, null,
            secondsSinceLastDeath: 30, recentOwnDeathCount: 0);
        Assert.Contains("SURVIVABILITY-FIRST CHECK", prompt);
        Assert.DoesNotContain("SUSTAIN-COMBAT CHECK", prompt);
    }

    [Fact]
    public void SustainCombatCheck_AbsentWhenSpiraling()
    {
        // In a death-spiral the `## Survival caution` owns it (max HP will not help while
        // the penalty re-stacks), so the "raise max HP" flee cue must yield.
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 5475), es, null, null, null, null,
            secondsSinceLastDeath: null, recentOwnDeathCount: 3);
        Assert.DoesNotContain("SUSTAIN-COMBAT CHECK", prompt);
    }

    [Fact]
    public void SustainCombatCheck_AbsentWhenNoUnspentXp()
    {
        // Fleeing but nothing to invest -> no cue.
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        var prompt = LlmGoalPolicy.BuildUserPrompt(
            BuildXpWorld(69296, 0), es, null, null, null, null,
            secondsSinceLastDeath: null, recentOwnDeathCount: 0);
        Assert.DoesNotContain("SUSTAIN-COMBAT CHECK", prompt);
    }

    // ---- IsWieldNoWeaponRepeat (cp041): the Motor rejects a Wield whose selector
    //      resolves to no equippable in-bag weapon; a model can re-emit it every
    //      cycle (e.g. trying to wield missile ammo with an empty quiver), burning
    //      LLM calls. After >=2 rejects the caller drops the Wield + defers. ----

    private static void AppendWieldNoWeaponFail(EventStream es)
        => es.Append(new StreamEvent
        {
            Sequence = -1, Utc = DateTimeOffset.UtcNow,
            Kind = EventKind.GoalFailed, GoalId = Guid.NewGuid(),
            // A Wield goal carries no Target, so the Motor's Fail Name is null; the
            // reason text is what the loop-break keys on. Mirrors HandshakeDriver
            // wrapped in TacticsExecutor's "{Kind}: {reason}" envelope.
            Name = null,
            Text = "Wield: wield: no equippable inventory weapon",
        });

    [Fact]
    public void IsWieldNoWeaponRepeat_TwoRejects_True()
    {
        var es = new EventStream();
        AppendWieldNoWeaponFail(es);
        AppendWieldNoWeaponFail(es);
        Assert.True(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_OneReject_False()
    {
        var es = new EventStream();
        AppendWieldNoWeaponFail(es);
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_OtherFailsDoNotCount()
    {
        // The low-health-defer / no-live-object / out-of-reach signals are distinct
        // and must not trip the wield loop-break.
        var es = new EventStream();
        AppendLowHealthDeferFail(es);
        AppendLowHealthDeferFail(es);
        AppendNoLiveObjectFail(es, "Corpse", kind: "Wield");
        AppendNoLiveObjectFail(es, "Corpse", kind: "Wield");
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_EmptyStream_False()
    {
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(new EventStream()));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_TwoRejects_AcrossPerceptionEviction_True()
    {
        // The futile Wields recur ACROSS decisions with heavy perception traffic between,
        // which evicts the first rejection from the perception-dominated ring. The DURABLE
        // GoalFailed window still holds both, so the loop-break can fire (it previously
        // fired only when two rejections were adjacent in the ring).
        var es = new EventStream();
        AppendWieldNoWeaponFail(es);
        // Flood well past the ring capacity so the first rejection is evicted from it.
        for (int i = 0; i < 400; i++)
            es.Append(new StreamEvent
            { Sequence = 0, Utc = DateTimeOffset.UtcNow, Kind = EventKind.HealthChanged });
        AppendWieldNoWeaponFail(es);
        Assert.True(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_SuccessfulWieldEmissionsDoNotCount()
    {
        // Counting must be on FAILURE semantics, not raw Wield emissions: a valid ammo
        // reload / shield equip is a SUCCESSFUL Wield (no no-weapon failure), so even many
        // Wield emissions with zero no-weapon rejections must NOT trip the loop-break.
        var es = new EventStream();
        for (int i = 0; i < 5; i++)
            es.Append(new StreamEvent
            {
                Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalEmitted,
                Text = "Wield target=<empty> item=name=\"Lead Pea\" source=llm:test",
            });
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void IsWieldNoWeaponRepeat_StaleFailuresAgeOut_WithOnlyPerceptionTraffic_False()
    {
        // The durable failure window must age out by TIME even when only non-failure
        // (perception) traffic follows -- otherwise two stale no-weapon failures would keep
        // the loop-break armed indefinitely and drop a later Wield on its first retry.
        var es = new EventStream();
        var t0 = new DateTimeOffset(2026, 6, 24, 12, 0, 0, TimeSpan.Zero);
        es.Append(new StreamEvent
        { Sequence = -1, Utc = t0, Kind = EventKind.GoalFailed, Text = "Wield: wield: no equippable inventory weapon" });
        es.Append(new StreamEvent
        { Sequence = -1, Utc = t0.AddSeconds(1), Kind = EventKind.GoalFailed, Text = "Wield: wield: no equippable inventory weapon" });
        Assert.True(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
        // Advance time past the 30-min retention with ONLY perception traffic (no new
        // failures); the stale failures must be pruned on this append.
        es.Append(new StreamEvent
        { Sequence = -1, Utc = t0.AddMinutes(31), Kind = EventKind.HealthChanged });
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

    [Fact]
    public void PruneGoalHistory_AgesOutStaleFailures_WithoutAnyAppend_False()
    {
        // The wall-clock stuck-timeout re-deliberation re-reads history with NO intervening
        // append, so retention must also be enforceable on demand: PruneGoalHistory(now)
        // drops the stale failures without needing a new event.
        var es = new EventStream();
        var t0 = new DateTimeOffset(2026, 6, 24, 12, 0, 0, TimeSpan.Zero);
        es.Append(new StreamEvent
        { Sequence = -1, Utc = t0, Kind = EventKind.GoalFailed, Text = "Wield: wield: no equippable inventory weapon" });
        es.Append(new StreamEvent
        { Sequence = -1, Utc = t0.AddSeconds(1), Kind = EventKind.GoalFailed, Text = "Wield: wield: no equippable inventory weapon" });
        Assert.True(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
        es.PruneGoalHistory(t0.AddMinutes(31)); // no append — just the on-demand prune
        Assert.False(LlmGoalPolicy.IsWieldNoWeaponRepeat(es));
    }

