        var hist = new[] { new CombatHistoryEntry("Mosswart", 8u, Kills: 0, Deaths: 0,
            NearDeaths: 2, Fights: 2, LastOutcome: "near-death", Ineffective: 0,
            MaxLossBotLevel: 9) };
