    private static StreamEvent WorldObjInteracted(string name, uint wcid, uint guid) => new()
    {
        Sequence = -1, Utc = DateTimeOffset.UtcNow,
        Kind = EventKind.WorldObjectInteracted,
        ItemGuid = guid, Wcid = wcid, Name = name,
    };

