                PositionX = 0, PositionY = 0, PositionZ = 0, HealthFraction = 1.0f, Level = 3,
            },
            Inventory = System.Array.Empty<InventoryItemProjection>(),
            Visible = visible,
            KilledKindsThisDwell = killed,
            CurrentFight = fight,
        };

