    // Returns just the named "## ..." section's text (header to the next "## ").
    private static string Cp068SectionText(string prompt, string header)
    {
        var start = prompt.IndexOf(header, StringComparison.Ordinal);
        if (start < 0) return string.Empty;
        var rest = prompt.IndexOf("\n## ", start + header.Length, StringComparison.Ordinal);
        return rest < 0 ? prompt.Substring(start) : prompt.Substring(start, rest - start);
    }

    [Fact]
    public void BuildUserPrompt_UnequippedGear_NoFalseAndMoreWhenDuplicateNamesCollapse()
    {
        // Two carried copies share a name; Distinct collapses to one, Take(4) never
        // fires, so the cue must NOT claim "and more" (no unnamed pieces exist).
        var inv = new[]
        {
            new InventoryItemProjection
            { Guid = 0x10u, Name = "Cap", Wcid = 100u, ValidLocations = Cp068WearSlotBit, WieldedAt = null },
            new InventoryItemProjection
            { Guid = 0x11u, Name = "Cap", Wcid = 100u, ValidLocations = Cp068WearSlotBit, WieldedAt = null },
        };
        var world = BuildInventoryWorld(inv);

        var prompt = LlmGoalPolicy.BuildUserPrompt(world, new EventStream(), null);
        var capsule = Cp068SectionText(prompt, "## Un-equipped gear");

        Assert.Contains("`Cap`", capsule);
        Assert.DoesNotContain("and more", capsule);
    }

    // ── cp069: single-NPC Talk-fixation backstop (goal-emission history) ──
    private static StreamEvent Cp069Emit(string kind, string target, DateTimeOffset utc) => new StreamEvent
    {
        Sequence = -1, Utc = utc, Kind = EventKind.GoalEmitted,
        Text = $"{kind} target=name=\"{target}\" item= source=llm:test",
    };

    private static EventStream Cp069Stream(params (string kind, string target)[] emissions)
    {
        var es = new EventStream();
        var t0 = DateTimeOffset.UtcNow.AddMinutes(-5);
        for (var i = 0; i < emissions.Length; i++)
            es.Append(Cp069Emit(emissions[i].kind, emissions[i].target, t0.AddSeconds(i)));
        return es;
    }

    private static Goal Cp069Talk(string npc) =>
        new Goal { Kind = GoalKind.Talk, Target = new Selector { Name = npc } };

    [Fact]
    public void CountTalkGoalsToNameInLastN_CountsTalksToName()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"));
        Assert.Equal(6, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "Greeter", 10));
    }

    [Fact]
    public void CountTalkGoalsToNameInLastN_WindowIsByGoalCount_OldestFallOut()
    {
        // 8 Talks to "Old" then 3 to "New" (11 emissions). Last-10 window drops the
        // single oldest "Old", so only 7 of the 8 "Old" Talks remain in window.
        var seq = new System.Collections.Generic.List<(string, string)>();
        for (var i = 0; i < 8; i++) seq.Add(("Talk", "Old"));
        for (var i = 0; i < 3; i++) seq.Add(("Talk", "New"));
        var es = Cp069Stream(seq.ToArray());
        Assert.Equal(7, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "Old", 10));
        Assert.Equal(3, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "New", 10));
    }

    [Fact]
    public void ProvenTalkFixationNameFromHistory_DominantPastThreshold_ReturnsName()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"));
        Assert.Equal("Greeter", LlmGoalPolicy.ProvenTalkFixationNameFromHistory(es));
    }

    [Fact]
    public void ProvenTalkFixationNameFromHistory_RoleSuffixedTargets_ReturnsBareName()
    {
        // A model that copies the rendered `Name "role"` label into the target
        // selector must still register as a fixation on the bare name (the Motor
        // resolves it that way; the history count must too — previously the
        // role-suffixed emissions keyed a different bucket and never crossed the
        // threshold).
        var es = Cp069Stream(
            ("Talk", "Greeter \"Society\""), ("Talk", "Greeter \"Society\""),
            ("Talk", "Greeter \"Society\""), ("Talk", "Greeter \"Society\""),
            ("Talk", "Greeter \"Society\""), ("Talk", "Greeter \"Society\""));
        Assert.Equal("Greeter", LlmGoalPolicy.ProvenTalkFixationNameFromHistory(es));
    }

    [Fact]
    public void CountTalkGoalsToNameInLastN_RoleSuffixedAndBare_CountTogether()
    {
        // Mixed bare + role-suffixed emissions to the same NPC accumulate under the
        // bare name (previously the role-suffixed ones matched 0).
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter \"Society\""),
            ("Talk", "Greeter \"Society\""));
        Assert.Equal(3, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "Greeter", 10));
    }

    [Fact]
    public void ProvenTalkFixationNameFromHistory_BelowThreshold_ReturnsNull()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Greeter"));   // only 5 < threshold 6
        Assert.Null(LlmGoalPolicy.ProvenTalkFixationNameFromHistory(es));
    }

    [Fact]
    public void ProvenTalkFixationNameFromHistory_NonTalkGoals_ReturnsNull()
    {
        var es = Cp069Stream(
            ("Attack", "Golem"), ("Explore", "anywhere"), ("Use", "Door"),
            ("Attack", "Golem"), ("Explore", "anywhere"), ("Attack", "Golem"));
        Assert.Null(LlmGoalPolicy.ProvenTalkFixationNameFromHistory(es));
    }

    [Theory]
    [InlineData("1", true)]
    [InlineData("true", true)]
    [InlineData("ON", true)]
    [InlineData(null, true)]      // default ON (unset)
    [InlineData("", true)]        // default ON (empty)
    [InlineData("0", false)]
    [InlineData("false", false)]
    [InlineData("off", false)]
    [InlineData("yes", true)]     // any non-off value stays ON
    public void ResolveSkipFixatedTalkCall_DefaultsOn_OptOutOnly(string? env, bool expected)
    {
        Assert.Equal(expected, LlmGoalPolicy.ResolveSkipFixatedTalkCall(env));
    }

    [Theory]
    [InlineData("1", true)]
    [InlineData("true", true)]
    [InlineData("ON", true)]
    [InlineData(null, true)]      // default ON (unset)
    [InlineData("", true)]        // default ON (empty)
    [InlineData("0", false)]
    [InlineData("false", false)]
    [InlineData("off", false)]
    [InlineData("yes", true)]     // any non-off value stays ON
    public void ResolveSkipEmptyExploreCall_DefaultsOn_OptOutOnly(string? env, bool expected)
    {
        Assert.Equal(expected, LlmGoalPolicy.ResolveSkipEmptyExploreCall(env));
    }

    private static Intent MakeStatusIntent(IntentLifecycle status) => new()
    {
        Id = "i-test",
        Kind = "quest:test",
        Rationale = "test",
        Completion = new KillCountSincePushAtLeastPredicate(3),
        Baseline = IntentBaseline.Capture(BuildImmobileWorld(0), new EventStream(), DateTime.UtcNow),
        Status = status,
    };

    [Fact]
    public void StackHasNoActiveObjective_NullStack_False()
        // A null stack = no intent system engaged (free-wandering); the skip gates
        // must STILL skip in this common case, so this is NOT "no active objective".
        => Assert.False(LlmGoalPolicy.StackHasNoActiveObjective(null));

    [Fact]
    public void StackHasNoActiveObjective_EmptyStack_True()
        => Assert.True(LlmGoalPolicy.StackHasNoActiveObjective(new IntentStack()));

    [Fact]
    public void StackHasNoActiveObjective_ActiveTop_False()
    {
        var stack = new IntentStack();
        Assert.Equal(StackOpResult.Ok, stack.TryPush(MakeStatusIntent(IntentLifecycle.Active)));
        Assert.False(LlmGoalPolicy.StackHasNoActiveObjective(stack));
    }

    [Fact]
    public void StackHasNoActiveObjective_BlockedTop_True()
    {
        // A root deadline-Blocked IN PLACE (Intent.CheckTopForCompletion) emits no
        // Goal lifecycle event, so the event-based completion guard misses it; this
        // status check is what makes the skip gates wake the LLM to re-plan.
        var stack = new IntentStack();
        Assert.Equal(StackOpResult.Ok, stack.TryPush(MakeStatusIntent(IntentLifecycle.Blocked)));
        Assert.True(LlmGoalPolicy.StackHasNoActiveObjective(stack));
    }

    [Fact]
    public void LastEmitWasUntargetedExplore_TrueWhenLastEmitIsExploreAnywhere()
    {
        var es = Cp069Stream(("Attack", "Golem"), ("Explore", "anywhere"));
        Assert.True(LlmGoalPolicy.LastEmitWasUntargetedExplore(es));
    }

    [Fact]
    public void LastEmitWasUntargetedExplore_FalseWhenLastEmitIsTargetedExplore()
    {
        // A targeted Explore (toward a named place/object) is a pursuit, not aimless
        // travel — the skip must not fire.
        var es = Cp069Stream(("Explore", "anywhere"), ("Explore", "Buckminster"));
        Assert.False(LlmGoalPolicy.LastEmitWasUntargetedExplore(es));
    }

    [Fact]
    public void LastEmitWasUntargetedExplore_FalseWhenLastEmitIsOtherVerb()
    {
        // The most-recent emit decides; a Talk after an Explore means the bot was
        // doing something concrete last.
        var es = Cp069Stream(("Explore", "anywhere"), ("Talk", "Greeter"));
        Assert.False(LlmGoalPolicy.LastEmitWasUntargetedExplore(es));
    }

    [Fact]
    public void LastEmitWasUntargetedExplore_FalseWhenNoEmits()
    {
        Assert.False(LlmGoalPolicy.LastEmitWasUntargetedExplore(new EventStream()));
    }

    [Fact]
    public void HasNewStrategicIntentCompletionSince_GoalIdLessLifecycle_True()
    {
        // An IntentStack auto-pop emits a GoalId-LESS GoalCompleted — a top-objective
        // change that must force a fresh LLM look (so it blocks the fixated-Talk skip).
        var es = new EventStream();
        var floor = es.NextSequence;
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalCompleted, GoalId = null });
        Assert.True(LlmGoalPolicy.HasNewStrategicIntentCompletionSince(es, floor));
    }

    [Fact]
    public void HasNewStrategicIntentCompletionSince_TacticalGoalChurn_False()
    {
        // A tactical goal completing carries a GoalId — ordinary churn, not a
        // strategic change, so it does NOT block the skip.
        var es = new EventStream();
        var floor = es.NextSequence;
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalCompleted, GoalId = Guid.NewGuid() });
        Assert.False(LlmGoalPolicy.HasNewStrategicIntentCompletionSince(es, floor));
    }

    [Fact]
    public void HasNewStrategicIntentCompletionSince_BelowFloor_False()
    {
        var es = new EventStream();
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.GoalCompleted, GoalId = null });
        var floor = es.NextSequence;   // strategic completion is BELOW the floor
        es.Append(new StreamEvent
        { Sequence = -1, Utc = DateTimeOffset.UtcNow, Kind = EventKind.ServerMessage, Text = "x" });
        Assert.False(LlmGoalPolicy.HasNewStrategicIntentCompletionSince(es, floor));
    }

    [Fact]
    public void CountTalkGoalsToNameInLastN_IgnoresNonTalkAndOtherNames()
    {
        var es = Cp069Stream(
            ("Attack", "Greeter"), ("Pickup", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Other"));
        Assert.Equal(2, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "Greeter", 10));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_FiresAtThreshold_InterleavedWithCombat()
    {
        // 6 Talks to one NPC interleaved with 4 Attacks (10 goals). The episode
        // guards would have reset on each kill; this history-based backstop fires.
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Talk", "Greeter"));
        Assert.True(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(Cp069Talk("Greeter"), es));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_DoesNotFireBelowThreshold()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"),
            ("Talk", "Greeter"), ("Attack", "Apple"));
        Assert.Equal(5, LlmGoalPolicy.CountTalkGoalsToNameInLastN(es, "Greeter", 10));
        Assert.False(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(Cp069Talk("Greeter"), es));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_DoesNotFireForNonTalkGoal()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"));
        var attack = new Goal { Kind = GoalKind.Attack, Target = new Selector { Name = "Greeter" } };
        Assert.False(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(attack, es));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_DoesNotFireWhenSpreadAcrossNpcs()
    {
        // 5 Talks each to two NPCs: neither alone reaches the single-NPC threshold.
        var es = Cp069Stream(
            ("Talk", "A"), ("Talk", "B"), ("Talk", "A"), ("Talk", "B"),
            ("Talk", "A"), ("Talk", "B"), ("Talk", "A"), ("Talk", "B"),
            ("Talk", "A"), ("Talk", "B"));
        Assert.False(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(Cp069Talk("A"), es));
        Assert.False(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(Cp069Talk("B"), es));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_MatchesNameContainsTarget()
    {
        var es = Cp069Stream(
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"),
            ("Talk", "Greeter"), ("Talk", "Greeter"), ("Talk", "Greeter"));
        var goal = new Goal { Kind = GoalKind.Talk, Target = new Selector { NameContains = "Greeter" } };
        Assert.True(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(goal, es));
    }

    [Fact]
    public void IsSingleNpcTalkFixationByHistory_EmptyHistory_DoesNotFire()
    {
        Assert.False(LlmGoalPolicy.IsSingleNpcTalkFixationByHistory(Cp069Talk("Greeter"), new EventStream()));
    }
